import csv
import io
import re


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )

    records = []
    for record in reader:
        if not record or all(not value.strip() for value in record):
            continue
        if record[0].lstrip().startswith("#"):
            continue
        records.append(record)

    if not records:
        return {"columns": [], "rows": []}

    numeric = re.compile(r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$")
    header_index = None

    for index, record in enumerate(records):
        if len(record) != 13:
            continue
        nonempty = [value.strip() for value in record if value.strip()]
        if nonempty and any(not numeric.fullmatch(value) for value in nonempty):
            header_index = index
            break

    if header_index is None:
        header_index = 0

    columns = list(records[header_index])
    data_records = records[header_index + 1:]

    max_width = max([len(columns)] + [len(row) for row in data_records])
    original_width = len(columns)
    for index in range(original_width, max_width):
        name = "extra_{}".format(index - original_width + 1)
        while name in columns:
            name += "_"
        columns.append(name)

    rows = []
    for record in data_records:
        row = list(record)
        row.extend([""] * (len(columns) - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
